import click
from click.testing import CliRunner

runner = CliRunner()

print('=== Test 1: default=True, flag_value=True, flag NOT provided ===')
@click.command()
@click.option('--foo', is_flag=True, type=bool, default=True, flag_value=True)
def cmd1(foo):
    click.echo(repr(foo), nl=False)
result = runner.invoke(cmd1, [])
print(f'Result: {result.output}')
print(f'Expected: True')
print()

print('=== Test 2: default=True, flag_value=False, flag NOT provided ===')
@click.command() 
@click.option('--foo', is_flag=True, type=bool, default=True, flag_value=False)
def cmd2(foo):
    click.echo(repr(foo), nl=False)
result = runner.invoke(cmd2, [])
print(f'Result: {result.output}')
print(f'Expected: False (this is the failing test)')
print()

print('=== Test 3: default=False, flag_value=True, flag NOT provided ===')  
