@click.option('--foo', is_flag=True, type=bool, default=False, flag_value=True)
def cmd3(foo):
    click.echo(repr(foo), nl=False)
result = runner.invoke(cmd3, [])
print(f'Result: {result.output}')
print(f'Expected: False')
print()

print('=== Test 4: default=False, flag_value=False, flag NOT provided ===')
